targets.root_selector:
([($names := {"base":"基準","diversified_alpha":"分散・alpha","diversified_all_eligible":"分散・全合格","liquidity_diversified":"流動性分散","conservative_diversified":"保守分散","high_score_conservative":"高分保守","arm_inert":"被風控壓成一組"}; $order := ["base","diversified_alpha","diversified_all_eligible","liquidity_diversified","conservative_diversified","high_score_conservative"]; $stats := latest_arm_statistics[$type(mean) = 'number']; $share := arm_share;
      $out := $order.($id := $; $st := $stats[arm_id = $id][0]; $s := $share[arm_id = $id][0].share;
        $st ? { 'name': $lookup($names, $id) & '｜' & $string($st.samples) & ' 樣本｜選用 ' & $string($round(($s ? $s : 0) * 100)) & '%', 'reward': $st.mean, 'arm': $id });
      $count($out) > 0 ? $out : [])])

([rows.{ 'model': model_name, 'gate': gate_decision, 'ic': ($ic := oos_ic; $lo := min_oos_ic_mean; $weak := weak_oos_ic_mean;
  $tier := $type($ic) != 'number' ? '' : $type($lo) = 'number' and $type($weak) = 'number' ? ($ic <= $lo ? 'bad' : $ic < $weak ? 'warn' : 'ok') : 'none';
  $tier ? $tier & '|' & $string($round($ic, 3)) : null),
      'state': ($w := $lookup({"production":"上線","approved":"已核准","archived":"已封存","shadowing":"影子中","approval_required":"待核准","rejected":"被拒","offline_failed":"離線未過","registration_failed":"註冊失敗"}, state); $w ? $w : state ? state : '—'),
      'min': 'IC 門檻 ' & $string(min_oos_ic_mean) & '（弱 ' & $string(weak_oos_ic_mean) & '，強 ' & $string(strong_oos_ic_mean) & '）', 'version': '版本 ' & champion_version,
      'run': source_run_date ? '訓練資料 ' & source_run_date : '訓練資料 —' }])

([($run := latest_monthly_run; $run.models.{ 'model': model_name, 'gate': gate_decision, 'ic': ($ic := oos_ic; $lo := min_oos_ic_mean; $weak := weak_oos_ic_mean;
  $tier := $type($ic) != 'number' ? '' : $type($lo) = 'number' and $type($weak) = 'number' ? ($ic <= $lo ? 'bad' : $ic < $weak ? 'warn' : 'ok') : 'none';
  $tier ? $tier & '|' & $string($round($ic, 3)) : null),
      'failed': $type(failed_gates) = 'array' and $count(failed_gates) > 0 ? $join([failed_gates.($w := $lookup({"artifact_registration_failed":"註冊失敗","model_cpcv_failed":"CPCV 未過","oos_ic_below_policy_floor":"OOS IC 低於門檻"}, $); $w ? $w : '其他閘門')], '、') : '—',
      'state': ($w := $lookup({"production":"上線","approved":"已核准","archived":"已封存","shadowing":"影子中","approval_required":"待核准","rejected":"被拒","offline_failed":"離線未過","registration_failed":"註冊失敗"}, state); $w ? $w : state ? state : '—'), 'live': $run.is_live ? '上線中' : '未上線',
      'run': $run.source_run_date ? '訓練資料 ' & $run.source_run_date : '訓練資料 —', 'version': '版本 ' & version })])
